SELECT data_rows.artifact_id, data_rows.should_delete, data_rows.artifact_ref, data_rows.owner_id, data_rows.owner_ref, data_rows.kind, data_rows.lifecycle, data_rows.version, data_rows.report_id, data_rows.title, data_rows.source_artifact_id, data_rows.base_artifact_ref, data_rows.policy_ref, data_rows.document_version, data_rows.report_document_json, data_rows.report_spec_json, data_rows.compile_state_json, data_rows.report_fill_json, data_rows.report_print_json, data_rows.saved_view_overlay_json, data_rows.metadata_json, data_rows.created_at, data_rows.updated_at FROM  (SELECT 0 AS should_delete, `artifact_id`, `artifact_ref`, `owner_id`, COALESCE(`owner_ref`, '') AS `owner_ref`, `kind`, `lifecycle`, `version`, COALESCE(`report_id`, '') AS `report_id`, COALESCE(`title`, '') AS `title`, COALESCE(`source_artifact_id`, '') AS `source_artifact_id`, COALESCE(`base_artifact_ref`, '') AS `base_artifact_ref`, COALESCE(`policy_ref`, '') AS `policy_ref`, `document_version`, `report_document_json`, `report_spec_json`, `compile_state_json`, `report_fill_json`, `report_print_json`, `saved_view_overlay_json`, `metadata_json`, `created_at`, `updated_at` FROM report_shared_artifact)  data_rows